(gen_random_uuid(), 'be06c56a-bee8-4467-b94d-f2d571c7d457', 'a', '158/102 mmHg em indivíduo diabético.', false),
(gen_random_uuid(), 'be06c56a-bee8-4467-b94d-f2d571c7d457', 'b', '174/66 mmHg com doença renal crônica.', false),
(gen_random_uuid(), 'be06c56a-bee8-4467-b94d-f2d571c7d457', 'c', '144/96 mmHg em indivíduos assintomáticos.', true),
(gen_random_uuid(), 'be06c56a-bee8-4467-b94d-f2d571c7d457', 'd', '160/104 mmHg com alteração vascular no fundo de olho.', false),
(gen_random_uuid(), 'be06c56a-bee8-4467-b94d-f2d571c7d457', 'e', '132/82 mmHg em grávida com 20 semanas de gestação.', false),

(gen_random_uuid(), '99a0689f-53e0-4c62-bb9c-e8c6bc7a12d5', 'a', 'A hipotensão ortostática é definida como redução da PA sistólica ≥ 20 mmHg ou na PA diastólica ≥ 10 mmHg dentro do terceiro minuto em pé em relação à posição supina. Deve ser investigada nos idosos, diabéticos, disautonômicos e inclusive naqueles pacientes em uso de anti-hipertensivos. Está associada a risco aumentado de mortalidade e eventos cardiovasculares.', true),
(gen_random_uuid(), '99a0689f-53e0-4c62-bb9c-e8c6bc7a12d5', 'b', 'O cálculo do índice tornozelo-braquial (ITB) pode ser realizado com o uso do Doppler, ou simplesmente pelo método oscilométrico. Enquanto maior o ITB, maior a mortalidade cardiovascular e maior a taxa de eventos coronários.', false),
(gen_random_uuid(), '99a0689f-53e0-4c62-bb9c-e8c6bc7a12d5', 'c', 'Uma diferença > 15 mmHg da pressão arterial sistólica entre os braços pode estar relacionada à doença vascular ateromatosa, mas não sugere aumento do risco cardiovascular.', false),
(gen_random_uuid(), '99a0689f-53e0-4c62-bb9c-e8c6bc7a12d5', 'd', 'Em cada consulta, três medidas da PA devem ser registradas, com 1 a 2 minutos de intervalo, e medidas adicionais devem ser realizadas se as duas primeiras leituras diferirem em mais de 10 mmHg. A PA do paciente é a maior das últimas duas medidas.', false),
(gen_random_uuid(), '99a0689f-53e0-4c62-bb9c-e8c6bc7a12d5', 'e', 'No método auscultatório, se os batimentos persistirem até o nível zero, determinar a PA diastólica (PAD) no abafamento dos sons (fase IV de Korotkoff) e anotar valores da PA sistólica/PAD/zero. Estenose aórtica é um exemplo desta condição.', false),

(gen_random_uuid(), '16c44dc9-6d6a-49c0-8375-19d6d1e925ff', 'a', 'A pandemia da COVID-19 fez com que a AMPA (automedida da pressão arterial) fosse adotada como substituta da MAPA (monitorização ambulatorial da pressão arterial) e da MRPA (monitorização residencial da pressão arterial) já que as técnicas são equivalentes.', false),
(gen_random_uuid(), '16c44dc9-6d6a-49c0-8375-19d6d1e925ff', 'b', 'O efeito do avental branco é a diferença da pressão arterial entre as medidas obtidas no consultório e fora dele, iguais ou superiores a 15 mmHg na pressão arterial sistólica e/ou 9 mmHg na pressão arterial diastólica, pela avaliação da MAPA (monitorização ambulatorial da pressão arterial).', false),
(gen_random_uuid(), '16c44dc9-6d6a-49c0-8375-19d6d1e925ff', 'c', 'A hipertensão do avental branco tem prevalência variada nos diferentes estudos, sendo mais comum entre os pré-hipertensos.', false),
(gen_random_uuid(), '16c44dc9-6d6a-49c0-8375-19d6d1e925ff', 'd', 'A confirmação do diagnóstico de hipertensão deve ser feita em duas ou mais visitas médicas, com intervalo de dias ou semanas; ou pela realização de medidas fora do consultório (monitorização ambulatorial da pressão arterial [MAPA] ou monitorização residencial da pressão arterial [MRPA]). No caso da MRPA considera-se como hipertensão valores ≥ 130 x 80 mmHg.', true),
(gen_random_uuid(), '16c44dc9-6d6a-49c0-8375-19d6d1e925ff', 'e', 'A hipertensão mascarada está associada a hipertensão estágio II, maior atividade adrenérgica e do sistema renina-angiotensina aldosterona e maior risco de morte súbita.', false),

(gen_random_uuid(), '6fc86847-c786-4183-a9a2-5cf37aee4aea', 'a', 'Hipertenso estágio I com risco adicional moderado.', true),
(gen_random_uuid(), '6fc86847-c786-4183-a9a2-5cf37aee4aea', 'b', 'Hipertenso estágio I com risco adicional baixo.', false),
(gen_random_uuid(), '6fc86847-c786-4183-a9a2-5cf37aee4aea', 'c', 'Hipertenso estágio II com risco adicional alto.', false),
(gen_random_uuid(), '6fc86847-c786-4183-a9a2-5cf37aee4aea', 'd', 'Hipertenso estágio II com risco adicional baixo.', false),
(gen_random_uuid(), '6fc86847-c786-4183-a9a2-5cf37aee4aea', 'e', 'Não hipertenso.', false),

(gen_random_uuid(), '1ceb228f-c7d2-4498-8e53-278b8053a427', 'a', 'A medida da PA em crianças é recomendada em toda avaliação clínica após os 3 anos de idade, pelo menos anualmente, como parte do seu atendimento pediátrico primário.', true),
(gen_random_uuid(), '1ceb228f-c7d2-4498-8e53-278b8053a427', 'b', 'Os aparelhos aneroides não são indicados por conta da descalibração indetectável.', false),
(gen_random_uuid(), '1ceb228f-c7d2-4498-8e53-278b8053a427', 'c', 'A interpretação dos valores de pressão arterial obtidos em crianças e adolescentes deve levar em conta a idade e o sexo, mas não a altura do paciente.', false),
(gen_random_uuid(), '1ceb228f-c7d2-4498-8e53-278b8053a427', 'd', 'Hipertensão arterial na criança é definida como pressão igual ou maior ao percentil 85 de distribuição da pressão arterial.', false),
(gen_random_uuid(), '1ceb228f-c7d2-4498-8e53-278b8053a427', 'e', 'Crianças não apresentam hipertensão de consultório e efeito do jaleco branco.', false),

(gen_random_uuid(), '922a85f0-44ce-450a-85ad-c77da4861087', 'a', 'monitorização residencial da pressão arterial (MRPA) está indicada quando a PA está elevada no consultório em indivíduos assintomáticos sem lesão de órgão-alvo e com baixo risco cardiovascular total', true),
(gen_random_uuid(), '922a85f0-44ce-450a-85ad-c77da4861087', 'b', 'MRPA está indicada quando há necessidade de avaliar o descenso durante o sono', false),
(gen_random_uuid(), '922a85f0-44ce-450a-85ad-c77da4861087', 'c', 'monitorização ambulatorial da PA (MAPA) é indicada para confirmação diagnóstica de hipertensão resistente; a MRPA não é indicada', false),
(gen_random_uuid(), '922a85f0-44ce-450a-85ad-c77da4861087', 'd', 'MAPA e MRPA não estão indicadas quando PA < 140 x 90 mmHg no consultório em indivíduos assintomáticos com lesão de órgão-alvo', false),
(gen_random_uuid(), '922a85f0-44ce-450a-85ad-c77da4861087', 'e', 'MRPA é indicada para a identificação do efeito do avental branco em hipertensos; MAPA não é indicada', false),

(gen_random_uuid(), '9fede685-6364-4965-9c49-0681758f5a7e', 'a', 'pode ser calculado com rapidez à beira do leito.', false),
(gen_random_uuid(), '9fede685-6364-4965-9c49-0681758f5a7e', 'b', 'índices iguais ou maiores que 1 são considerados anormais.', true),
(gen_random_uuid(), '9fede685-6364-4965-9c49-0681758f5a7e', 'c', 'os registros da pressão arterial na perna de indivíduos com vasos calcificados não são confiáveis para uso.', false),
(gen_random_uuid(), '9fede685-6364-4965-9c49-0681758f5a7e', 'd', 'é a relação entre a pressão arterial sistólica medida no tornozelo com a pressão arterial sistólica medida na artéria braquial.', false),
(gen_random_uuid(), '9fede685-6364-4965-9c49-0681758f5a7e', 'e', 'em pacientes com úlceras cutâneas, uma pressão no tornozelo menor que 55mmHg prediz cicatrização inadequada da úlcera.', false),

(gen_random_uuid(), 'b1accb8b-6841-461d-9f88-1525c964dfd3', 'a', 'Realizar exercícios físicos 30 minutos antes da medida.', true),
(gen_random_uuid(), 'b1accb8b-6841-461d-9f88-1525c964dfd3', 'b', 'Colocar o manguito 2 a 3 cm acima da fossa cubital.', false),
(gen_random_uuid(), 'b1accb8b-6841-461d-9f88-1525c964dfd3', 'c', 'Inflar rapidamente até ultrapassar 20 a 30 mmHg o nível estimado da pressão arterial sistólica (PAS) obtido pela palpação.', false),
(gen_random_uuid(), 'b1accb8b-6841-461d-9f88-1525c964dfd3', 'd', 'Determinar a pressão arterial sistólica (PAS) pela ausculta do primeiro som e, após, aumentar ligeiramente a velocidade de deflação.', false),
(gen_random_uuid(), 'b1accb8b-6841-461d-9f88-1525c964dfd3', 'e', 'Determinar a pressão arterial diastólica (PAD) no desaparecimento dos sons.', false),

(gen_random_uuid(), '5f842694-e9e7-4264-a961-22fe243becad', 'a', 'Eletrocardiograma com hipertrofia ventricular esquerda (Sokolow-Lyon > 35mm).', false),
(gen_random_uuid(), '5f842694-e9e7-4264-a961-22fe243becad', 'b', 'Espessura mediointimal de carótida > 0,9 mm ou presença de placa de ateroma.', false),
(gen_random_uuid(), '5f842694-e9e7-4264-a961-22fe243becad', 'c', 'Ritmo de filtração glomerular ou clearance de creatinina < 60 mL/min.', false),
(gen_random_uuid(), '5f842694-e9e7-4264-a961-22fe243becad', 'd', 'Microalbuminúria acima de 300 mg/24 h ou relação albumina/creatinina < 30 mg por g.', true),
(gen_random_uuid(), '5f842694-e9e7-4264-a961-22fe243becad', 'e', 'Índice tornozelo-braquial < 0,9.', false),

(gen_random_uuid(), '36cc86af-eab0-4c87-8bfc-fc3a5d968df6', 'a', 'Os BCCs, em geral, podem provocar hiperplasia gengival – um efeito adverso reversível se detectado precocemente.', true),
(gen_random_uuid(), '36cc86af-eab0-4c87-8bfc-fc3a5d968df6', 'b', 'Seu uso requer monitorização seriada de eletrólitos pelo risco de hipocalcemia grave.', false),
(gen_random_uuid(), '36cc86af-eab0-4c87-8bfc-fc3a5d968df6', 'c', 'O anlodipino, que pertence ao grupo dos não diidropiridínicos, é o fármaco mais bem estudado dessa classe de medicamentos.', false),
(gen_random_uuid(), '36cc86af-eab0-4c87-8bfc-fc3a5d968df6', 'd', 'O edema maleolar costuma ser efeito colateral raro, comum a todos os medicamentos dessa classe, resultando da própria ação vasodilatadora (mais arterial que venosa) e promovendo a transudação capilar.', false),
(gen_random_uuid(), '36cc86af-eab0-4c87-8bfc-fc3a5d968df6', 'e', 'Recomenda-se o uso de anlodipino em doses fracionadas de 6/6h devido ao seu tempo de meia-vida curto.', false),

(gen_random_uuid(), 'a823b5ed-9e44-4d6f-874d-6606dd37a9cc', 'a', 'Manter o esquema terapêutico e investigar hipertensão secundária.', false),
(gen_random_uuid(), 'a823b5ed-9e44-4d6f-874d-6606dd37a9cc', 'b', 'Manter o esquema terapêutico por se tratar de hipertensão resistente do avental branco.', false),
(gen_random_uuid(), 'a823b5ed-9e44-4d6f-874d-6606dd37a9cc', 'c', 'Iniciar espironolactona e investigar apneia obstrutiva do sono.', true),
(gen_random_uuid(), 'a823b5ed-9e44-4d6f-874d-6606dd37a9cc', 'd', 'Iniciar dose noturna de betabloqueador, visando à melhora do comportamento pressórico no sono.', false),
(gen_random_uuid(), 'a823b5ed-9e44-4d6f-874d-6606dd37a9cc', 'e', 'Suspender clortalidona e iniciar dose noturna de simpaticolítico de ação central.', false),

(gen_random_uuid(), '023c73d8-a5d8-416a-a598-49188d3f163a', 'a', 'Orientações rígidas quanto à redução do consumo de sal e abandono do sedentarismo, manutenção da medicação e controle clínico em 30 dias para avaliar a pressão arterial e alteração na medicação.', false),
(gen_random_uuid(), '023c73d8-a5d8-416a-a598-49188d3f163a', 'b', 'Adição de carvedilol 3,125 mg BID, espironolactona 25 mg e dieta hipossódica.', false),
(gen_random_uuid(), '023c73d8-a5d8-416a-a598-49188d3f163a', 'c', 'Encaminhamento à reabilitação cardiovascular para atividade física adequada e à nutricionista para dieta individualizada, com controle clínico em 90 dias para reavaliação.', false),
(gen_random_uuid(), '023c73d8-a5d8-416a-a598-49188d3f163a', 'd', 'Aumento do maleato de enalapril para 10 mg, 2 vezes ao dia, adição de besilato de anlodipino 5 mg, orientações quanto à redução do consumo de sal e abandono do sedentarismo.', true),
(gen_random_uuid(), '023c73d8-a5d8-416a-a598-49188d3f163a', 'e', 'Manutenção do enalapril 10 mg, com adição de losartana potássica 50 mg e atenolol 25 mg, além de dieta hipossódica e hipolipídica.', false),

(gen_random_uuid(), '9abcc37d-dbf0-4daa-9799-d010018d9602', 'a', 'Essas drogas não exercem efeito na resistência vascular periférica mesmo em uso prolongado.', false),
(gen_random_uuid(), '9abcc37d-dbf0-4daa-9799-d010018d9602', 'b', 'Seu efeito anti-hipertensivo tem estreita relação com a dose utilizada, assim como seus efeitos colaterais.', false),
(gen_random_uuid(), '9abcc37d-dbf0-4daa-9799-d010018d9602', 'c', 'A clortalidona tem uma maior potência diurética e meia-vida mais prolongada quando comparada à hidroclorotiazida; tem sido considerada o diurético de escolha para pacientes com hipertensão arterial sistêmica (HAS) resistente ou refratária.', true),
(gen_random_uuid(), '9abcc37d-dbf0-4daa-9799-d010018d9602', 'd', 'Essas drogas são classicamente usadas para o tratamento de hipertensão e ainda hoje são a primeira opção para o tratamento inicial em monoterapia.', false),
(gen_random_uuid(), '9abcc37d-dbf0-4daa-9799-d010018d9602', 'e', 'Os diuréticos poupadores de potássio não devem ser utilizados em associação com os tiazídicos ou os diuréticos de alça.', false),

(gen_random_uuid(), '7a9adce9-efef-4f6a-a200-440c3a225b9d', 'a', 'hipertensão refratária', false),
(gen_random_uuid(), '7a9adce9-efef-4f6a-a200-440c3a225b9d', 'b', 'hipertensão resistente.', false),
(gen_random_uuid(), '7a9adce9-efef-4f6a-a200-440c3a225b9d', 'c', 'hipertensão secundária.', false),
(gen_random_uuid(), '7a9adce9-efef-4f6a-a200-440c3a225b9d', 'd', 'encefalopatia hipertensiva.', false),
(gen_random_uuid(), '7a9adce9-efef-4f6a-a200-440c3a225b9d', 'e', 'hipertensão maligna acelerada.', true),

(gen_random_uuid(), 'd44e2ae2-1eac-4ef9-9bb0-2ce3eb67ef95', 'a', 'hipertensão refratária; iniciar espironolactona em doses baixas e clonidina noturna', false),
(gen_random_uuid(), 'd44e2ae2-1eac-4ef9-9bb0-2ce3eb67ef95', 'b', 'hipertensão resistente; iniciar espironolactona em doses baixas', true),
(gen_random_uuid(), 'd44e2ae2-1eac-4ef9-9bb0-2ce3eb67ef95', 'c', 'hipertensão resistente; iniciar betabloqueador e uso de pressão positiva contínua nas vias aéreas (CPAP)', false),
(gen_random_uuid(), 'd44e2ae2-1eac-4ef9-9bb0-2ce3eb67ef95', 'd', 'hipertensão refratária; iniciar espironolactona e avaliar pressão positiva contínua nas vias aéreas (CPAP)', false),
(gen_random_uuid(), 'd44e2ae2-1eac-4ef9-9bb0-2ce3eb67ef95', 'e', 'hipertensão resistente; iniciar betabloqueador pela manhã e clonidina noturna', false),

(gen_random_uuid(), '70ab6549-7358-4a7a-a4e2-0c44402e6fa1', 'a', 'trocar inibidor da enzima conversora da angiotensina (iECA) por bloqueadores dos receptores da angiotensina (BRA) e associar nitrato e hidralazina, buscando melhor controle pressórico e proteção miocárdica', false),
(gen_random_uuid(), '70ab6549-7358-4a7a-a4e2-0c44402e6fa1', 'b', 'otimizar a dose do iECA e iniciar atenolol, por ser mais potente do que os betabloqueadores de terceira geração para controle da frequência cardíaca', false),
(gen_random_uuid(), '70ab6549-7358-4a7a-a4e2-0c44402e6fa1', 'c', 'otimizar a dose do iECA e da atorvastatina, além de iniciar metformina e betabloqueador', true),
(gen_random_uuid(), '70ab6549-7358-4a7a-a4e2-0c44402e6fa1', 'd', 'trocar anlodipino por bloqueador de cálcio não diidropiridínico, já que o paciente tem contraindicação ao uso do betabloqueador, iniciar metformina e otimizar a dose da atorvastatina', false),
(gen_random_uuid(), '70ab6549-7358-4a7a-a4e2-0c44402e6fa1', 'e', 'otimizar a dose do iECA e atorvastatina e iniciar diurético tiazídico e nitrato para melhor controle pressórico e proteção miocárdica', false),

(gen_random_uuid(), '47e7025b-5f35-47af-9efe-9d84eacb04b6', 'a', 'é um procedimento baseado no racional de que há intensa inervação simpática ao redor dos rins.', false),
(gen_random_uuid(), '47e7025b-5f35-47af-9efe-9d84eacb04b6', 'b', 'se trata de procedimento já com indicação clínica para hipertensão arterial resistente consolidada.', false),
(gen_random_uuid(), '47e7025b-5f35-47af-9efe-9d84eacb04b6', 'c', 'a técnica mais consagrada envolve disparos de radiofrequência aplicados na parede externa das artérias renais bilateralmente.', false),
(gen_random_uuid(), '47e7025b-5f35-47af-9efe-9d84eacb04b6', 'd', 'resultados mais recentes mostraram redução da pressão arterial semelhante a placebo e têm colocado em dúvida a utilidade do procedimento.', true),
(gen_random_uuid(), '47e7025b-5f35-47af-9efe-9d84eacb04b6', 'e', 'os estudos Simplicity foram os que incluíram o maior número de hipertensos não controlados em uso de 2 anti-hipertensivos submetidos a essa estratégia.', false),

(gen_random_uuid(), '00ff799e-dfcd-4eaf-9888-2c9a90beaaa9', 'a', 'A potência diurética da clortalidona é menor que a da hidroclorotiazida quando comparadas dose a dose, e sua meia-vida, mais curta.', false),
(gen_random_uuid(), '00ff799e-dfcd-4eaf-9888-2c9a90beaaa9', 'b', 'A indapamida, um tiazídico-símile, tem baixa potência e efeito diurético curto.', false),
(gen_random_uuid(), '00ff799e-dfcd-4eaf-9888-2c9a90beaaa9', 'c', 'Deve-se dar preferência aos DIU tiazídicos (hidroclorotiazida) ou similares (clortalidona e indapamida) em doses baixas, pois são mais suaves e com maior tempo de ação que os DIU de alça.', true),
(gen_random_uuid(), '00ff799e-dfcd-4eaf-9888-2c9a90beaaa9', 'd', 'A hipocalcemia induzida por diuréticos reduz a liberação de insulina, aumentando a intolerância à glicose e o risco de desenvolver diabetes melito tipo 2.', false),
(gen_random_uuid(), '00ff799e-dfcd-4eaf-9888-2c9a90beaaa9', 'e', 'Os diuréticos não estão associados à disfunção erétil.', false),

(gen_random_uuid(), 'd64ae4c3-855f-437e-8328-f66880fc664c', 'a', 'Inibidor sistema renina-angiotensina-aldosterona (SRAA) + betabloqueador, por promoverem nefroproteção e pelo alto risco de doença coronariana associada.', false),
(gen_random_uuid(), 'd64ae4c3-855f-437e-8328-f66880fc664c', 'b', 'Tiazídico + bloqueador de canal de cálcio, para melhor redução da pressão arterial sistólica.', false),
(gen_random_uuid(), 'd64ae4c3-855f-437e-8328-f66880fc664c', 'c', 'Inibidor do sistema renina-angiotensina-aldosterona (SRAA) + espironolactona + hidralazina, visando à remodelação cardíaca.', false),
(gen_random_uuid(), 'd64ae4c3-855f-437e-8328-f66880fc664c', 'd', 'Associar inibidor da enzima conversora da angiotensina (iECA) + bloqueador de receptores da angiotensina (BRA), para inibição dupla do sistema renina-angiotensina-aldosterona (SRAA), por se tratar de paciente jovem com síndrome metabólica e proteinúria.', false),
(gen_random_uuid(), 'd64ae4c3-855f-437e-8328-f66880fc664c', 'e', 'Inibidor sistema renina-angiotensina-aldosterona (SRAA) + bloqueador de canal de cálcio, por inibirem a progressão do remodelamento cardíaco e promoverem a nefroproteção.', true),

