(gen_random_uuid(), '32272427-0cec-4665-b4d7-74c23dc28629', 'a', 'Hipertensão estágio 2 e alto risco cardiovascular. Conduta: melhorar adesão e usar combinação de dois fármacos, sendo um inibidor do sistema renina-angiotensina-aldosterona em associação com betabloqueador.', false),
(gen_random_uuid(), '32272427-0cec-4665-b4d7-74c23dc28629', 'b', 'Hipertensão estágio 2 e alto risco cardiovascular. Conduta: melhorar adesão e usar combinação de dois fármacos, sendo um inibidor do sistema renina-angiotensina-aldosterona em associação com antagonista de cálcio ou diurético, além de redução de peso.', true),
(gen_random_uuid(), '32272427-0cec-4665-b4d7-74c23dc28629', 'c', 'Hipertensão estágio 2 e alto risco cardiovascular. Conduta: melhorar adesão terapêutica com o inibidor do sistema renina-angiotensina-aldosterona já em uso, pois na presença de hipertrofia ventricular esquerda esta é a melhor classe de anti-hipertensivos.', false),
(gen_random_uuid(), '32272427-0cec-4665-b4d7-74c23dc28629', 'd', 'Hipertensão estágio 3 e alto risco cardiovascular. Conduta: melhorar adesão e usar combinação de três fármacos, sendo um inibidor do sistema renina-angiotensina-aldosterona em associação com antagonista dos canais de cálcio e betabloqueador para controle da frequência cardíaca.', false),
(gen_random_uuid(), '32272427-0cec-4665-b4d7-74c23dc28629', 'e', 'Trata-se de um caso de hipertensão resistente, e a adição de espironolactona é a escolha correta.', false),

(gen_random_uuid(), '4f73621a-b0cd-47f2-a1b6-b9194f921449', 'a', 'trocar diurético de alça por um tiazídico e iniciar um inibidor do sistema renina-angiotensina-aldosterona (SRAA), objetivando melhor controle pressórico, proteção renal e reversão da hipertrofia ventricular esquerda', true),
(gen_random_uuid(), '4f73621a-b0cd-47f2-a1b6-b9194f921449', 'b', 'associar espironolactona pela possibilidade de hiperaldosteronismo diante do potássio baixo, objetivando melhor controle pressórico e consequente melhoria da função renal', false),
(gen_random_uuid(), '4f73621a-b0cd-47f2-a1b6-b9194f921449', 'c', 'suspender toda a medicação e iniciar um inibidor do SRAA e metformina, visando à proteção renal', false),
(gen_random_uuid(), '4f73621a-b0cd-47f2-a1b6-b9194f921449', 'd', 'aumentar a dose da furosemida para 80 mg/dia e iniciar investigação para doença renovascular', false),
(gen_random_uuid(), '4f73621a-b0cd-47f2-a1b6-b9194f921449', 'e', 'iniciar duplo bloqueio do SRAA, com objetivo de reduzir os níveis de albuminúria e reverter hipertrofia ventricular esquerda', false),

(gen_random_uuid(), '8171825c-8b23-43af-a1ef-4023f2674493', 'a', 'Controle da hipertensão arterial com losartana potássica e solicitação das dosagens de sódio, potássio e aldosterona urinárias.', false),
(gen_random_uuid(), '8171825c-8b23-43af-a1ef-4023f2674493', 'b', 'Controle da hipertensão arterial com espironolactona e solicitação de tomografia computadorizada de cortes finos com especial atenção às adrenais.', false),
(gen_random_uuid(), '8171825c-8b23-43af-a1ef-4023f2674493', 'c', 'Controle da hipertensão arterial com a combinação hidroclorotiazida + amilorida e solicitação de aldosterona e renina séricas, metanefrinas urinárias e cortisol salivar.', false),
(gen_random_uuid(), '8171825c-8b23-43af-a1ef-4023f2674493', 'd', 'Controle da hipertensão arterial com besilato de anlodipino, suplementação de cloreto de potássio e solicitação de dosagens de aldosterona e renina séricas.', true),
(gen_random_uuid(), '8171825c-8b23-43af-a1ef-4023f2674493', 'e', 'Controle da hipertensão arterial com doxazosina e realização do teste com captopril (dosagem de aldosterona antes, 60'' e 120'' após o uso de 50mg de captopril oral).', false),

(gen_random_uuid(), '9fab136e-3c23-4260-acf2-87b67bbed385', 'a', 'Na presença de hipercalemia e relação aldosterona/ácido vanilmandélico estável.', false),
(gen_random_uuid(), '9fab136e-3c23-4260-acf2-87b67bbed385', 'b', 'Quando se detecta incidentaloma, realizar aldosterona urinária de 24h.', false),
(gen_random_uuid(), '9fab136e-3c23-4260-acf2-87b67bbed385', 'c', 'Na presença de hipocalemia e relação aldosterona plasmática/atividade plasmática de renina maior que 30.', true),
(gen_random_uuid(), '9fab136e-3c23-4260-acf2-87b67bbed385', 'd', 'Na presença de hipertensão resistente, realizar aldosterona urinária em amostra de urina isolada.', false),
(gen_random_uuid(), '9fab136e-3c23-4260-acf2-87b67bbed385', 'e', 'Na presença de hipertensão resistente realizar, dosagem de ácido vanilmandélico em urina 24h.', false),

(gen_random_uuid(), '91de8bfe-4b4f-44bc-9559-2ed99dd52154', 'a', 'suspender espironolactona por quatro a seis semanas e dosar aldosterona sérica e atividade de renina plasmática', true),
(gen_random_uuid(), '91de8bfe-4b4f-44bc-9559-2ed99dd52154', 'b', 'suspender espironolactona por quatro a seis semanas e losartana por três semanas e dosar aldosterona sérica e atividade de renina plasmática', false),
(gen_random_uuid(), '91de8bfe-4b4f-44bc-9559-2ed99dd52154', 'c', 'manter toda a medicação para evitar o descontrole pressórico e solicitar exame de imagem das adrenais', false),
(gen_random_uuid(), '91de8bfe-4b4f-44bc-9559-2ed99dd52154', 'd', 'não tem indicação de investigar hiperaldosteronismo primário, já que a MAPA está controlada', false),
