(gen_random_uuid(), 'f1cf392e-448f-4157-9f61-c7f517e1ab53', 'c', 'Idade < 40 anos.', false),
(gen_random_uuid(), 'f1cf392e-448f-4157-9f61-c7f517e1ab53', 'd', 'Presença de sobrepeso.', false),
(gen_random_uuid(), 'f1cf392e-448f-4157-9f61-c7f517e1ab53', 'e', 'História familiar de doença cardiovascular prematura.', false),

(gen_random_uuid(), 'dc45f138-8824-420b-81dd-73447604f395', 'a', 'os ajustes de dose devem ser realizados a cada seis semanas, para evitar reduções abruptas de pressão arterial', false),
(gen_random_uuid(), 'dc45f138-8824-420b-81dd-73447604f395', 'b', 'todos os idosos entre 65 e 80 anos, independentemente dos critérios de fragilidade, devem manter pressão arterial sistólica ≤ 130 mmHg', false),
(gen_random_uuid(), 'dc45f138-8824-420b-81dd-73447604f395', 'c', 'no idoso, as metas terapêuticas devem ser individualizadas, baseadas no julgamento da equipe multidisciplinar e considerando suas preferências', true),
(gen_random_uuid(), 'dc45f138-8824-420b-81dd-73447604f395', 'd', 'os betabloqueadores menos lipossolúveis como o atenolol não são recomendados para idosos por seu maior risco de efeito colateral no sistema nervoso central (depressão, sonolência, confusão, distúrbio do sono)', false),
(gen_random_uuid(), 'dc45f138-8824-420b-81dd-73447604f395', 'e', 'o envelhecimento produz alterações vasculares, como: enrijecimento arterial, aumento da complacência vascular, aumento da pressão arterial sistólica e maior sensibilidade a mudanças de volume', false),

(gen_random_uuid(), '6f5428b8-f360-446a-b9a7-65104531c9c1', 'a', 'Teste confirmatório para diagnóstico com furosemida ou sobrecarga salina.', true),
(gen_random_uuid(), '6f5428b8-f360-446a-b9a7-65104531c9c1', 'b', 'Interromper a avaliação devido à baixa probabilidade de hiperaldosteronismo.', false),
(gen_random_uuid(), '6f5428b8-f360-446a-b9a7-65104531c9c1', 'c', 'Repetir a dosagem hormonal após suspensão de diurético e inibidores do sistema renina-angiotensina-aldosterona (SRAA).', false),
(gen_random_uuid(), '6f5428b8-f360-446a-b9a7-65104531c9c1', 'd', 'Ressonância magnética das adrenais.', false),
(gen_random_uuid(), '6f5428b8-f360-446a-b9a7-65104531c9c1', 'e', 'Cateterismo de veias adrenais para diferenciar adenoma e hiperplasia de suprarrenal.', false),

(gen_random_uuid(), '8a459f59-3d9f-49e5-bb69-da1b3b10574c', 'a', 'Para o diagnóstico de hipertensão resistente verdadeira é obrigatória a realização da avaliação da pressão arterial fora do consultório (monitorização ambulatorial da pressão arterial [MAPA] ou monitorização residencial da pressão arterial [MRPA]) para exclusão do efeito do avental branco.', true),
(gen_random_uuid(), '8a459f59-3d9f-49e5-bb69-da1b3b10574c', 'b', 'Trata-se de hipertensão pseudorresistente verdadeira e, como o esquema tríplice não alcançou as metas, está recomendado o quarto fármaco, que deve ser preferencialmente clonidina, já que em homens há o risco de ginecomastia com espironolactona.', false),
(gen_random_uuid(), '8a459f59-3d9f-49e5-bb69-da1b3b10574c', 'c', 'Trata-se de hipertensão refratária e, como a ativação parassimpática exacerbada é a principal fisiopatologia, a quarta droga deve ser um betabloqueador.', false),
(gen_random_uuid(), '8a459f59-3d9f-49e5-bb69-da1b3b10574c', 'd', 'Como os exames laboratoriais e o eletrocardiograma estão normais, trata-se de um caso de pseudorresistência e nenhum ajuste terapêutico é necessário.', false),
(gen_random_uuid(), '8a459f59-3d9f-49e5-bb69-da1b3b10574c', 'e', 'A denervação simpática renal diminui ação simpática sobre coração e vasos. Como esse paciente tem frequência cardíaca elevada, claramente tem ativação simpática e deveria ser encaminhado para realização do procedimento.', false),

(gen_random_uuid(), '984bfffc-5a2c-475a-b222-64556706f0c5', 'a', 'dosagem de catecolaminas urinárias devido aos paroxismos noturnos da pressão arterial e iniciar alfa1-bloqueadores pela suspeita de feocromocitoma', false),
(gen_random_uuid(), '984bfffc-5a2c-475a-b222-64556706f0c5', 'b', 'polissonografia e indicação de pressão positiva contínua em vias aéreas (CPAP) em caso de apneia moderada/grave', true),
(gen_random_uuid(), '984bfffc-5a2c-475a-b222-64556706f0c5', 'c', 'solicitar exame de imagem das adrenais e aumentar a espironolactona para 100 mg/dia em caso de hiperplasia adrenal', false),
(gen_random_uuid(), '984bfffc-5a2c-475a-b222-64556706f0c5', 'd', 'polissonografia e início de um hipnótico indutor de sono em caso de redução do sono REM com índice de apneia/hipopneia = 19/hora', false),
(gen_random_uuid(), '984bfffc-5a2c-475a-b222-64556706f0c5', 'e', 'aumentar a dose da clonidina noturna e solicitar nova MAPA por se tratar de um hipertenso refratário', false),

(gen_random_uuid(), '21426c4d-df99-43a5-bd71-8bf40ff81341', 'a', 'Hipertensão mascarada. Reavaliar em 2 meses para definição diagnóstica e terapêutica.', false),
(gen_random_uuid(), '21426c4d-df99-43a5-bd71-8bf40ff81341', 'b', 'Hipertensão do avental branco. Reavaliar em 2 meses para definição diagnóstica e terapêutica.', false),
(gen_random_uuid(), '21426c4d-df99-43a5-bd71-8bf40ff81341', 'c', 'Hipertensão mascarada. Promover mudanças de estilo de vida e iniciar terapia combinada, incluindo inibidor do sistema renina-angiotensina-aldosterona (SRAA).', true),
(gen_random_uuid(), '21426c4d-df99-43a5-bd71-8bf40ff81341', 'd', 'Hipertensão mascarada. Promover mudanças de estilo de vida e iniciar betabloqueador cardiosseletivo (nebivolol) ou alfa-agonista central, para reduzir a hiperatividade simpática responsável pelo fenômeno do jaleco branco.', false),
(gen_random_uuid(), '21426c4d-df99-43a5-bd71-8bf40ff81341', 'e', 'Hipertensão do avental branco. Promover mudanças de estilo de vida e acompanhar com medidas domiciliares e clonidina de resgate.', false),

(gen_random_uuid(), 'caddef6e-af96-438e-9c8a-512d6d09c0cf', 'a', 'O tratamento deve ser iniciado, preferencialmente, com um DIU e, caso a meta pressórica não seja alcançada, deverá ser associado um BB, iECA ou BRA e BCC.', false),
(gen_random_uuid(), 'caddef6e-af96-438e-9c8a-512d6d09c0cf', 'b', 'O tratamento deve ser iniciado, preferencialmente, com um BB ou um DIU, considerando-se o baixo custo dessas medicações, exceto em condições especiais.', false),
(gen_random_uuid(), 'caddef6e-af96-438e-9c8a-512d6d09c0cf', 'c', 'O tratamento deve ser iniciado, preferencialmente, com monoterapia a ser escolhida entre DIU, BB, BCC, BRA ou iECA.', false),
(gen_random_uuid(), 'caddef6e-af96-438e-9c8a-512d6d09c0cf', 'd', 'O tratamento deve ser iniciado, preferencialmente, com uma combinação de dois fármacos escolhidos entre um iECA/BRA, DIU e BCC.', true),
(gen_random_uuid(), 'caddef6e-af96-438e-9c8a-512d6d09c0cf', 'e', 'O tratamento deve ser iniciado, preferencialmente, com a combinação de um iECA e um BB que tenham demonstrado superioridade na redução da incidência de insuficiência cardíaca.', false),

(gen_random_uuid(), '6b0c015d-6b80-43cf-8304-0814afaf6023', 'a', 'apenas a assertiva III está correta.', true),
(gen_random_uuid(), '6b0c015d-6b80-43cf-8304-0814afaf6023', 'b', 'apenas as assertivas I e II estão corretas', false),
(gen_random_uuid(), '6b0c015d-6b80-43cf-8304-0814afaf6023', 'c', 'apenas as assertivas I e III estão corretas', false),
(gen_random_uuid(), '6b0c015d-6b80-43cf-8304-0814afaf6023', 'd', 'apenas as assertivas II e III estão corretas', false),
(gen_random_uuid(), '6b0c015d-6b80-43cf-8304-0814afaf6023', 'e', 'todas as assertivas estão corretas', false),

(gen_random_uuid(), '6fe28b37-f1d8-4ac0-9b62-ed11ed629e79', 'a', 'No teste, razão aldosterona/renina plasmática, valores acima de 30 ng/dL confirmam o diagnóstico', false),
(gen_random_uuid(), '6fe28b37-f1d8-4ac0-9b62-ed11ed629e79', 'b', 'As características tomográficas do nódulo na adrenal esquerda sugerem adenoma', true),
(gen_random_uuid(), '6fe28b37-f1d8-4ac0-9b62-ed11ed629e79', 'c', 'A cateterização de veias renais para dosagem de aldosterona é opcional', false),
(gen_random_uuid(), '6fe28b37-f1d8-4ac0-9b62-ed11ed629e79', 'd', 'O teste com sobrecarga salina (2L de SF em 4h) não se justifica quando a razão aldosterona/renina plasmática está aumentada', false),
(gen_random_uuid(), '6fe28b37-f1d8-4ac0-9b62-ed11ed629e79', 'e', 'O risco cardiovascular do paciente com hiperaldo primário é semelhante ao do paciente com HAS primária', false),

(gen_random_uuid(), 'a7a321d6-7a6e-4e04-a95c-47a26c87f343', 'a', 'insuficiência renal.', false),
(gen_random_uuid(), 'a7a321d6-7a6e-4e04-a95c-47a26c87f343', 'b', 'hiperaldosteronismo', false),
(gen_random_uuid(), 'a7a321d6-7a6e-4e04-a95c-47a26c87f343', 'c', 'estenose de artéria renal.', false),
(gen_random_uuid(), 'a7a321d6-7a6e-4e04-a95c-47a26c87f343', 'd', 'secreção inapropriada de cortisol.', false),
(gen_random_uuid(), 'a7a321d6-7a6e-4e04-a95c-47a26c87f343', 'e', 'síndrome da apneia-hipopneia obstrutiva do sono.', true),

(gen_random_uuid(), 'be9a3ada-5ff1-48e7-8856-4456c7a3849d', 'a', 'Feito diagnóstico de hipertensão arterial, devendo ser iniciado o tratamento.', true),
