(gen_random_uuid(), 'be9a3ada-5ff1-48e7-8856-4456c7a3849d', 'c', 'Solicitar monitorização ambulatorial da pressão arterial (MAPA) para confirmação do diagnóstico de hipertensão arterial.', false),
(gen_random_uuid(), 'be9a3ada-5ff1-48e7-8856-4456c7a3849d', 'd', 'Confirmar o diagnóstico com mais uma medida de consultório elevada e após repetir a MRPA ou MAPA.', false),
